class Solution {
    private final int mod = (int) 1e9 + 7;

    public int cuttingBamboo(int n) {
        if (n < 4) {
            return n - 1;
        }
        if (n % 3 == 0) {
            return qpow(3, n / 3);
        }
        if (n % 3 == 1) {
            return (int) (4L * qpow(3, n / 3 - 1) % mod);
        }
        return 2 * qpow(3, n / 3) % mod;
    }

    private int qpow(long a, long n) {
        long ans = 1;
        for (; n > 0; n >>= 1) {
            if ((n & 1) == 1) {
                ans = ans * a % mod;
            }
            a = a * a % mod;
        }
        return (int) ans;
    }
}

